const input = items[0].json;
const clean = (value, limit) => String(value || '').replace(/[\x00-\x1f\x7f]/g, ' ').slice(0, limit);
const workflowId = clean(input.workflow?.id, 80);
if (!/^[A-Za-z0-9_-]{1,80}$/.test(workflowId)) throw new Error('Invalid workflow identity');
const name = clean(input.workflow?.name, 120) || workflowId;
const executionId = clean(input.execution?.id, 24);
if (executionId && !/^[0-9]{1,24}$/.test(executionId)) throw new Error('Invalid execution identity');
const handlerId = String($execution.id);
if (!/^[0-9]{1,24}$/.test(handlerId)) throw new Error('Invalid handler execution identity');
const node = clean(input.execution?.lastNodeExecuted, 120);
const base = 'https://n8n.socrat.alchemmist.xyz/workflow/' + encodeURIComponent(workflowId);
const url = executionId ? base + '/executions/' + executionId : base;
const description = ['Workflow: ' + name, executionId ? 'Execution: ' + executionId : 'Trigger failure (no execution ID)', node ? 'Failed node: ' + node : '', 'Open the protected execution page for error details.'].filter(Boolean).join('\n');
// Intentionally never forward error.message/stack/context, headers or node inputs.
return [{json:{chat_id:891074228,alert:{status:'firing',fingerprint:'n8n-' + workflowId + '-' + (executionId || 'trigger-' + handlerId),startsAt:new Date().toISOString(),generatorURL:url,labels:{alertname:'N8nWorkflowExecutionFailed',component:'n8n',namespace:'automation',severity:'warning',workflow_id:workflowId},annotations:{summary:'n8n workflow failed: ' + name,description}}}}];
